#include <vector>
#include <string>

using namespace std;

class Solution {
    vector<int> parent;

    int find(int x) {
        if (x != parent[x])
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }

    bool isSimilar(const string& a, const string& b) {
        int diff = 0;
        for (int i = 0; i < a.size(); ++i)
            if (a[i] != b[i] && ++diff > 2)
                return false;
        return true;
    }

public:
    int numSimilarGroups(vector<string>& strs) {
        int n = strs.size();
        parent.resize(n);
        for (int i = 0; i < n; ++i)
            parent[i] = i;

        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j)
                if (isSimilar(strs[i], strs[j]))
                    unite(i, j);

        int groups = 0;
        for (int i = 0; i < n; ++i)
            if (find(i) == i)
                ++groups;
        return groups;
    }
};
